using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Inventory.Domain;
public sealed class StockAllocation:Entity<Guid>{private StockAllocation(){}private StockAllocation(Guid id,Guid tenantId,Guid electionId,Guid itemId,Guid sourceWarehouseId,Guid? teamId,Guid? pollingCenterId,Guid recipientId,short stateId,decimal quantity){if(tenantId==Guid.Empty||electionId==Guid.Empty||itemId==Guid.Empty||sourceWarehouseId==Guid.Empty||recipientId==Guid.Empty)throw new ArgumentException("Allocation references are required.");if(teamId is null&&pollingCenterId is null)throw new ArgumentException("Team or polling center is required.");if(stateId<=0||quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));Id=id;TenantId=tenantId;ElectionId=electionId;ItemId=itemId;SourceWarehouseId=sourceWarehouseId;TeamId=teamId;PollingCenterId=pollingCenterId;RecipientUserId=recipientId;StateId=stateId;Quantity=decimal.Round(quantity,3);CreatedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public Guid ItemId{get;private set;}public Guid SourceWarehouseId{get;private set;}public Guid? TeamId{get;private set;}public Guid? PollingCenterId{get;private set;}public Guid RecipientUserId{get;private set;}public short StateId{get;private set;}public decimal Quantity{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset? AcknowledgedAtUtc{get;private set;}public static StockAllocation Create(Guid tenantId,Guid electionId,Guid itemId,Guid warehouseId,Guid? teamId,Guid? centerId,Guid recipientId,short stateId,decimal quantity)=>new(Guid.NewGuid(),tenantId,electionId,itemId,warehouseId,teamId,centerId,recipientId,stateId,quantity);public void Acknowledge(){if(AcknowledgedAtUtc is not null)throw new InvalidOperationException("Already acknowledged.");AcknowledgedAtUtc=DateTimeOffset.UtcNow;}public void MoveTo(short stateId){if(stateId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));StateId=stateId;}}
